import queryString from 'query-string';
import {
  BrowserClient,
  defaultStackParser,
  getDefaultIntegrations,
  makeFetchTransport,
  Scope,
} from '@sentry/browser';

import config from './config';
import {
  embedSocure,
  embedNeuroId,
  embedIovation,
  embedThreatmetrix,
  embedSocureDigitalIntelligence,
  removeIovation,
  removeNeuroId,
  removeSocure,
  removeSocureDigitalIntelligence,
  removeThreatmetrix,
} from './services';
import { initBC } from './services/initBC';
import { Alloy, ClientServices, Init, InitResult, JourneyData } from './types';
import {
  fetchAuthInit,
  generateJourneyApplication,
  generateEvaluation,
  fetchPublicInfo,
} from './utils/api';
import getEmbeddedDataSources from './utils/dataSources';
import version from './version';

const alloyId = 'alloy';
const alloyInitParams: InitResult = { key: '', npmPackageVersion: version };
let alloyCallback: (arg0: any) => void;
let iframeSrc: string;
let sentryTelemetry: boolean = true;

// filter Sentry integrations that use the global variable
const integrations = getDefaultIntegrations({}).filter(
  (defaultIntegration) => {
    return !["BrowserApiErrors", "Breadcrumbs", "GlobalHandlers"].includes(
      defaultIntegration.name,
    );
  },
);
const client = new BrowserClient({
  dsn: "https://daf0ad474f2a2a0fb3429754a44caa47@o478884.ingest.us.sentry.io/4509204292894721",
  release: `alloy-web-sdk@${version}`,
  stackParser: defaultStackParser,
  integrations,
  transport: makeFetchTransport,
});
const sentryScope = new Scope();
sentryScope.setClient(client);
client.init(); // initializing has to be done after setting the client on the scope

const createEvaluation = async () => {
  removeNeuroId();
  const {
    key,
    entityToken,
    evaluationData,
    production,
    externalEntityId,
    socureDeviceId,
    socureSessionToken,
    iovationBlackboxId,
    neuroIdSiteId,
    threatmetrixSessionId,
    threatmetrixOrgId,
  } = alloyInitParams;
  const { access_token: token } = await fetchAuthInit(key);
  const isNeuroIdEnabled = !!neuroIdSiteId;
  const currEntityToken = entityToken;

  const embeddedDataSources = getEmbeddedDataSources({
    socureDeviceId,
    socureSessionToken,
    isNeuroIdEnabled,
    neuroIdSiteId,
    iovationBlackboxId,
    threatmetrixSessionId,
    threatmetrixOrgId,
  });

  const data = {
    ...evaluationData,
    ...embeddedDataSources,
  };

  const evaluation = await generateEvaluation(
    token,
    data,
    currEntityToken,
    externalEntityId,
    production,
  );
  return evaluation;
};

const createJourneyApplication = async (data: JourneyData) => {
  removeNeuroId();
  const {
    key,
    journeyToken,
    production,
    socureDeviceId,
    socureSessionToken,
    iovationBlackboxId,
    neuroIdSiteId,
    threatmetrixSessionId,
    threatmetrixOrgId,
  } = alloyInitParams;

  if (journeyToken) {
    const journeyData = data;

    const { access_token: token } = await fetchAuthInit(key);
    const isNeuroIdEnabled = !!neuroIdSiteId;

    const embeddedDataSources = getEmbeddedDataSources({
      socureDeviceId,
      socureSessionToken,
      isNeuroIdEnabled,
      neuroIdSiteId,
      iovationBlackboxId,
      threatmetrixSessionId,
      threatmetrixOrgId,
    });

    if (Object.keys(embeddedDataSources).length >= 1) {
      journeyData.entities = data.entities?.map(entity => {
        const entityWithDeviceId = entity;
        entityWithDeviceId.data = {
          ...entityWithDeviceId.data,
          ...embeddedDataSources,
        };
        return entityWithDeviceId;
      });
    }

    const journeyApplicationResponse = await generateJourneyApplication(
      journeyToken,
      token,
      journeyData,
      production,
    );
    alloyInitParams.journeyApplicationToken =
      journeyApplicationResponse.journey_application_token;
    return journeyApplicationResponse;
  }
  return null;
};

const close = () => {
  try {
    removeNeuroId(true);
    removeIovation();
    removeSocure();
    removeSocureDigitalIntelligence();
    removeThreatmetrix();
    const element = document.getElementById(alloyId);
    if (element && element.parentNode) {
      element.parentNode.removeChild(element);
    }
  } catch (err) {
    if (sentryTelemetry) {
      sentryScope.captureException(err);
    }
  }
};

const fetchClientServices = async (key): Promise<ClientServices> => {
  const { access_token: accessToken } = await fetchAuthInit(key);
  const publicInfo = await fetchPublicInfo(key, accessToken);
  const isNeuroIdEnabled = publicInfo?.services?.neuro_id || false;
  const neuroIdSiteId = publicInfo?.services?.neuro_id?.siteId || '';
  const isThreatmetrixEnabled = publicInfo?.services?.threatmetrix || false;
  const threatmetrixOrgId = publicInfo?.services?.threatmetrix?.orgId || '';
  const isIovationEnabled = publicInfo?.services?.iovation || false;
  const isSocureEnabled = publicInfo?.services?.socure_dv || false;
  const socurePublicToken =
    publicInfo?.services?.socure_dv?.publicToken || false;
  const isSocureDigitalIntelEnabled =
    publicInfo?.services?.socure_digital_intel || false;
  const socureDigitalIntelPublicToken =
    publicInfo?.services?.socure_digital_intel?.publicToken || '';
  const bcJsUrl = publicInfo?.services?.bc?.jsUrl || '';
  const bcBrand = publicInfo?.services?.bc?.brand || '';

  return {
    bcJsUrl,
    bcBrand,
    isNeuroIdEnabled,
    neuroIdSiteId,
    isIovationEnabled,
    isSocureEnabled,
    socurePublicToken,
    isThreatmetrixEnabled,
    threatmetrixOrgId,
    isSocureDigitalIntelEnabled,
    socureDigitalIntelPublicToken,
  };
};

const init = async ({
  key,
  apiUrl,
  appUrl,
  entityToken,
  externalEntityId,
  evaluationData,
  production,
  maxEvaluationAttempts,
  documents,
  selfie,
  color,
  customStyle,
  customerSlug,
  forceMobile,
  validationPreChecks,
  showHeader,
  journeyApplicationToken,
  journeyToken,
  isSingleEntity,
  isReactNative,
  isAndroidDevice,
  neuroUserId,
  neuroIdFunnel,
  socureCustomerSessionId,
  bcContext: bcContextFromClient,
  bcCustomerSessionId: bcCustomerSessionIdFromClient,
  telemetry = true,
}: Init): Promise<InitResult> => {
  sentryTelemetry = telemetry;

  try {
    // reset any residual init params when first initializing
    Object.keys(alloyInitParams).forEach(alloyKey => {
      delete alloyInitParams[alloyKey];
    });

    alloyInitParams.key = key;
    alloyInitParams.npmPackageVersion = version;
    if (customerSlug) {
      const sdkApiUrl = `https://${customerSlug}-alloysdk.api.alloy.com/`;
      const codelessUrl = `https://${customerSlug}-alloysdk.app.alloy.com/`;
      config.codeless = codelessUrl;
      config.api = sdkApiUrl;
    }
    // TODO: Remove once provisioning works on customerSlug basis
    if (apiUrl && appUrl) {
      config.codeless = appUrl;
      config.api = apiUrl;
    }
    if (entityToken) {
      alloyInitParams.entityToken = entityToken;
    }
    if (externalEntityId) {
      alloyInitParams.externalEntityId = externalEntityId;
    }
    if (production) {
      alloyInitParams.production = production;
    }
    if (maxEvaluationAttempts) {
      alloyInitParams.maxEvaluationAttempts = maxEvaluationAttempts;
    }
    if (documents) {
      alloyInitParams.documents = documents;
    }
    if (selfie) {
      alloyInitParams.selfie = selfie;
    }
    if (forceMobile) {
      alloyInitParams.forceMobile = forceMobile;
    }
    if (showHeader === false) {
      alloyInitParams.showHeader = showHeader;
    }
    if (validationPreChecks) {
      alloyInitParams.validationPreChecks = validationPreChecks;
    }
    if (journeyApplicationToken) {
      alloyInitParams.journeyApplicationToken = journeyApplicationToken;
    }
    if (journeyToken) {
      alloyInitParams.journeyToken = journeyToken;
    }
    if (isSingleEntity) {
      alloyInitParams.isSingleEntity = isSingleEntity;
    }

    const {
      isNeuroIdEnabled,
      neuroIdSiteId,
      isThreatmetrixEnabled,
      threatmetrixOrgId,
      isIovationEnabled,
      isSocureEnabled,
      socurePublicToken,
      isSocureDigitalIntelEnabled,
      socureDigitalIntelPublicToken,
      bcBrand: bcBrandFromAdmin,
      bcJsUrl: bcJsUrlFromAdmin,
    } = await fetchClientServices(key);

    if (socurePublicToken && isSocureEnabled) {
      alloyInitParams.socurePublicToken = socurePublicToken;
      const socureDeviceId = await embedSocure(socurePublicToken);
      alloyInitParams.socureDeviceId = socureDeviceId;
    }

    if (socureDigitalIntelPublicToken && isSocureDigitalIntelEnabled) {
      alloyInitParams.socureDigitalIntelPublicToken = socureDigitalIntelPublicToken;
      const socureSessionToken = await embedSocureDigitalIntelligence({
        sdkKey: socureDigitalIntelPublicToken,
        customerSessionId: socureCustomerSessionId,
      });
      alloyInitParams.socureSessionToken = socureSessionToken;
    }

    if (isNeuroIdEnabled && neuroIdSiteId) {
      alloyInitParams.neuroIdSiteId = neuroIdSiteId;
      const identityId = embedNeuroId(
        neuroUserId,
        neuroIdSiteId,
        production || false,
        neuroIdFunnel,
      );
      // neuroUserId is alloy's internal mapping for identityId
      alloyInitParams.neuroUserId = identityId;
      if (neuroIdFunnel) {
        alloyInitParams.neuroIdFunnel = neuroIdFunnel;
      }
    }

    if (isThreatmetrixEnabled && threatmetrixOrgId) {
      alloyInitParams.threatmetrixOrgId = threatmetrixOrgId;
      const sessionId = embedThreatmetrix(threatmetrixOrgId);
      alloyInitParams.threatmetrixSessionId = sessionId;
    }
    // if there is a jsUrl set, we know we are using bc
    const bcJsUrl = bcJsUrlFromAdmin;

    if (bcJsUrl) {
      const bcBrand = bcBrandFromAdmin;
      const bcContext = bcContextFromClient;
      if (!bcBrand || !bcContext) {
        console.error(
          'The Alloy framework has not been initialized.  If "jsUrl" is provided then "brand" and "context" are required',
        );
      } else {
        const bcInitResult = await initBC({
          brand: bcBrand,
          customerSessionId: bcCustomerSessionIdFromClient,
          context: bcContext,
          jsUrl: bcJsUrl,
        });

        // customerSessionId may be set by the initBC call, so we should use that.
        alloyInitParams.bcCustomerSessionId = bcInitResult.customerSessionId;
        alloyInitParams.bcBrand = bcBrand;
        alloyInitParams.bcContext = bcContext;
        alloyInitParams.bcJsUrl = bcJsUrl;
        alloyInitParams.bcCdApi = bcInitResult.cdApi;
      }
    }

    if (isIovationEnabled) {
      const blackboxId = await embedIovation();
      alloyInitParams.iovationBlackboxId = blackboxId;
    }
    if (isReactNative) {
      alloyInitParams.isReactNative = isReactNative;
    }

    if (isAndroidDevice) {
      alloyInitParams.isAndroidDevice = isAndroidDevice;
    }

    // parse the theme and component customization object into a string and pass it along to SDK UI.
    const themeString = JSON.stringify(customStyle?.theme);
    const componentOverrideString = JSON.stringify(
      customStyle?.componentOverride,
    );
    const themeObject = {
      theme: themeString,
    };
    const componentOverrideObject = {
      componentOverride: componentOverrideString,
    };

    iframeSrc = `${queryString.stringify(alloyInitParams)}${
      evaluationData ? `&${queryString.stringify(evaluationData)}` : ''
    }${color ? `&${queryString.stringify(color)}` : ''}${
      themeObject.theme ? `&${queryString.stringify(themeObject)}` : ''
    }${
      componentOverrideObject.componentOverride
        ? `&${queryString.stringify(componentOverrideObject)}`
        : ''
    }`;

    if (evaluationData) {
      alloyInitParams.evaluationData = evaluationData;
    }
  } catch (err) {
    if (sentryTelemetry) {
      sentryScope.captureException(err);
    }
  }

  return alloyInitParams;
};

const getPublicUrl = () => {
  let publicUrl = `${config.codeless}?${iframeSrc}`;
  try {
    if (
      alloyInitParams.journeyApplicationToken &&
      !publicUrl.includes('journeyApplicationToken')
    ) {
      publicUrl = `${config.codeless}?${iframeSrc}&journeyApplicationToken=${alloyInitParams.journeyApplicationToken}`;
    }
  } catch (err) {
    if (sentryTelemetry) {
      sentryScope.captureException(err);
    }
  }
  return publicUrl;
};

const open = (cb: (data: any) => void, anchorElement?: string) => {
  try {
    removeNeuroId();
    const eventListener = (event: any) => {
      const isAlloyUrl =
        event.origin === 'https://docv-iframe.alloy.co' ||
        event.origin === 'https://alloysdk.alloy.co' ||
        event.origin.includes('.app.alloy.com')

      if (!isAlloyUrl || !alloyCallback) {
        return;
      }
      window.removeEventListener('message', eventListener);
      alloyCallback(event.data);
      close();
    };
    window.addEventListener('message', eventListener);
    alloyCallback = cb;
    if (!alloyInitParams.key) {
      // eslint-disable-next-line no-console
      console.error(
        'The Alloy framework has not been initialized. You are missing the sdk key in your initialize parameters.',
      );
    } else {
      const alloyHeadStyles = document.getElementById('alloy-iframe-style');
      if (!alloyHeadStyles) {
        document.head.insertAdjacentHTML(
          'beforeend',
          `<style id="alloy-iframe-style">
          @keyframes fade {
            0%, 40% { opacity: 0 }
            80% { opacity: 1 }
          }
          @keyframes slideopen {
            from {
              margin-top: 100%;
            }

            to {
              margin-top: 0%;
            }
          }
          .alloy-container {
            height: 100%;
            width: 100%;
            position: fixed;
            top: 0;
            transform: none;
            left: 0;
            z-index: 2;
          }
          @media (min-width: 768px) {
            .alloy-container {
              animation: slideopen 1s linear;
              height: 720px;
              position: absolute;
              left: 50%;
              top: 50%;
              transform: translate(-50%, -50%);
              width: 50rem;
            }
          }
          .alloy-iframe {
              animation: fade 1.5s linear;
              border: 0;
              opacity: 1;
              height: 100%;
              max-height: 100%;
              width: 100%;
          }
          @media (min-width: 768px) {
              .alloy-iframe {
                border-radius: 1rem;
                box-shadow: 0 10px 20px 0 rgba(63,83,92,0.3);
                overflow: scroll;
              }
            }</style>`,
        );
      }

      let container = document.getElementById(alloyId);
      if (!container) {
        container = document.createElement('div');
        container.className = 'alloy-container';
        const alloyIframe = document.createElement('iframe');
        alloyIframe.id = 'alloyIframe';
        alloyIframe.src = getPublicUrl();
        alloyIframe.allow = 'autoplay; camera; microphone; fullscreen; accelerometer; magnetometer; gyroscope; picture-in-picture';
        alloyIframe.className = 'alloy-iframe';
        container.id = alloyId;
        document.body.appendChild(container);
        container.appendChild(alloyIframe);

        if (anchorElement && document.getElementById('alloy')) {
          const idAnchor = document.getElementById(anchorElement);
          const classAnchor = document.getElementsByClassName(anchorElement);
          if (idAnchor) {
            idAnchor.insertAdjacentElement(
              'afterbegin',
              document.getElementById('alloy')!,
            );
          } else if (classAnchor[0]) {
            classAnchor[0].insertAdjacentElement(
              'afterbegin',
              document.getElementById('alloy')!,
            );
          }
        }
      }
    }
  } catch (err) {
    if (sentryTelemetry) {
      sentryScope.captureException(err);
    }
  }
};

const alloy: Alloy = {
  init,
  open,
  close,
  createJourneyApplication,
  createEvaluation,
  getPublicUrl,
};
export { Init };

export default alloy;
