export const getSessionIdValidationError = (
  sessionId: string,
): string | null => {
  if (!sessionId) {
    return 'the session id is not set';
  }
  // noinspection SuspiciousTypeOfGuard
  if (typeof sessionId !== 'string') {
    return 'the session id must be a string';
  }
  if (sessionId.length < 10 || sessionId.length > 100) {
    return 'the session id must be between 10 and 100 characters long';
  }
  const validCharsRegex = /^[A-Za-z0-9!@$%^&*.=+/_~-]+$/;
  if (!validCharsRegex.test(sessionId)) {
    return 'the session id must only contain the characters A-Za-z0-9,!@$%^&*.=+/_~- ';
  }
  return null;
};

/**
 * Create a unique Customer Session ID
 *
 * Create a unique string between 10 and 100 characters
 * containing A-Za-z0-9,!@$%^&*.=+-_/\~
 *
 * @see {@link https://DOCS/docs/js-mandatory-functions#setcustomersessionid}
 */
export const createUniqueBCSessionId = (
  minLength: number = 10,
  maxLength: number = 100,
) => {
  const sessionIdLength =
    Math.floor(Math.random() * (maxLength - minLength + 1)) + minLength;
  if (sessionIdLength < minLength || sessionIdLength > maxLength) {
    // sanity check---this shouldn't ever happen
    throw new Error(
      `Internal Error: invalid sessionIdLength: ${sessionIdLength}`,
    );
  }
  // noinspection SpellCheckingInspection
  const chars =
    'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!@$%^&*.=+-_/~';
  let result = '';
  for (let i = sessionIdLength; i > 0; i -= 1)
    result += chars[Math.floor(Math.random() * chars.length)];
  return result;
};

/**
 * Configuration options for embedding the BC SDK
 */
export interface BCEmbedOptions {
  customerSessionId: string;
  context: string;
  brand: string;
  jsUrl: string;
}

/**
 * result of embedding the BC SDK is the cdApi
 */
export interface BCEmbedResult {
  cdApi: typeof window.cdApi;
}

const validateOrThrowError = (options: BCEmbedOptions) => {
  if (!options) {
    throw new Error(
      'Invalid or missing options.  Please provide an object containing the customerSessionId, the context, and the brand.',
    );
  }

  // noinspection SuspiciousTypeOfGuard
  if (!options.context || typeof options.context !== 'string') {
    throw new Error(
      'Invalid or missing context. It must be a non-empty string.',
    );
  }

  // noinspection SuspiciousTypeOfGuard
  if (!options.brand || typeof options.brand !== 'string') {
    throw new Error('Invalid or missing brand. It must be a non-empty string.');
  }

  // noinspection SuspiciousTypeOfGuard
  if (!options.jsUrl || typeof options.jsUrl !== 'string') {
    throw new Error(
      'Invalid or missing jsUrl.  This will be the js/sdk url provided by BC.',
    );
  }
};

/**
 * Load the bc js frontend, and call the mandatory functions
 *
 * This will return the bc cdApi object (though it should also
 * be available at window.cdApi)
 *
 * @see {@link https://DOCS/docs/js-mandatory-functions}
 */
export default (options: BCEmbedOptions): Promise<BCEmbedResult> => {
  validateOrThrowError(options);

  const script: HTMLScriptElement = document.createElement('script');
  script.type = 'text/javascript';
  script.src = options.jsUrl;
  script.async = true;

  if (window.cdApi) {
    // TODO: BC warns that this may be a problem---right now we will
    // have a warning, but I think we should throw an error.  If an sdk is
    // already initialized, we might accidentally hijack another ongoing session.
    console.warn('BC SDK already loaded.');
  }

  document.head.appendChild(script);

  return new Promise((resolve, reject) => {
    script.onload = () => {
      try {
        window.cdApi.setCustomerSessionId(options.customerSessionId);
        window.cdApi.changeContext(options.context);
        window.cdApi.setCustomerBrand(options.brand);
        resolve({
          cdApi: window.cdApi,
        });
      } catch (e) {
        reject(e);
      }
    };
    script.onerror = e => {
      reject(e);
    };
  });
};
