export type SigmaDeviceOptions = {
  sdkKey: string;
  configBaseUrl?: string;
  useSocureGov?: boolean;
  customerSessionId?: string;
  disableDeviceCookie?: boolean;
  deviceCookieName?: string;
}

declare const SigmaDeviceManager: {
  initialize: ( options: SigmaDeviceOptions ) => void
  getSessionToken: () => Promise<string>;
};

export const SOCURE_DI_DOMAIN_KEY = 'sdk.dv.socure.io';

export default async (sigmaDeviceOptions: SigmaDeviceOptions) => {
  // Create script
  const script: HTMLScriptElement = document.createElement('script');
  script.src = `https://${SOCURE_DI_DOMAIN_KEY}/latest/device-risk-sdk.js`;
  script.type = 'text/javascript';
  script.defer = true;
  script.setAttribute('data-status', 'loading');

  // Add script to document body
  document.head.appendChild(script);

  // create promise to await get session token
  const socureSessionToken = await new Promise<string>((resolve) => {   
    const getSessionToken = () => {
      // remove listener after enter the first time
      script.removeEventListener('load', getSessionToken);
      try {
        SigmaDeviceManager.initialize(sigmaDeviceOptions);
        SigmaDeviceManager.getSessionToken().then((sessionToken: string) => {
          resolve(sessionToken);
        });
      } catch (err) {
        resolve('');
      }
    };

    // wait for script to be fully loaded
    script.addEventListener('load', getSessionToken);
  });
  return socureSessionToken;
}

export const removeSocureDigitalIntelligence = () => {
  const scripts = document.querySelectorAll('script');
  scripts.forEach(script => {
    if (script.src.includes(SOCURE_DI_DOMAIN_KEY)) {
      script.remove();
    }
  });
}