const getEmbeddedDataSources = ({
  socureDeviceId, socureSessionToken, isNeuroIdEnabled, neuroIdSiteId, iovationBlackboxId, threatmetrixSessionId, threatmetrixOrgId,
}) => {
  const sources: any = {};
  if (socureDeviceId) sources.socure_session_id = socureDeviceId;
  if (socureSessionToken) sources.socure_session_id = socureSessionToken;
  if (isNeuroIdEnabled && neuroIdSiteId) {
    const identityId = sessionStorage.getItem('identityId');
    sources.neuro_user_id = identityId;
    sources.site_id = neuroIdSiteId;
  } 
  if (threatmetrixSessionId) {
    sources.threatmetrix_session_id = threatmetrixSessionId;
    sources.org_id = threatmetrixOrgId;
  }
  if (iovationBlackboxId) {
    sources.iovation_blackbox = iovationBlackboxId;
  }
  return sources;
}

export default getEmbeddedDataSources;