import { setSessionId } from "./helpers";

const THREATMETRIX_DOMAIN_KEY = 'h.online-metrix.net';

export default (orgId: string) => {

  const sessionId = setSessionId('tmSessionId');

  // Sanitize orgId and sessionId by ensuring they are safe to use
  const safeOrgId = encodeURIComponent(orgId);   // Encoding the values
  const safeSessionId = encodeURIComponent(sessionId);

  // Create script
  const script: HTMLScriptElement = document.createElement('script');
  script.type = 'text/javascript';
  script.src = `https://${THREATMETRIX_DOMAIN_KEY}/fp/tags?org_id=${safeOrgId}&session_id=${safeSessionId}`;
  script.async = true;

  // Add script to document 
  document.head.appendChild(script);

  return sessionId;
} 

export const removeThreatmetrix = () => {
  const scripts = document.querySelectorAll('script');
  scripts.forEach(script => {
    if (script.src.includes(THREATMETRIX_DOMAIN_KEY)) {
      script.remove();
    }
  });
}