import embedBC, { BCEmbedOptions, createUniqueBCSessionId } from './embedBC';

export interface BCInitOptions {
  customerSessionId?: string;
  context: string;
  brand: string;
  jsUrl: string;
}

export interface BCInitResult {
  cdApi: typeof window.cdApi;
  customerSessionId: string;
}

export const hasMissingOptions = (options: BCInitOptions): string | null => {
  if (!options) {
    return 'Invalid or missing options.  Please provide an object containing the customerSessionId, the context, and the brand.';
  }
  if (!options.brand) {
    return '"brand" is required';
  }
  if (!options.context) {
    return '"context" is required';
  }
  if (!options.jsUrl) {
    return '"jsUrl" is required';
  }
  return null;
};

/**
 * Initialize BC.
 *
 * If the caller does not pass in a bc session id, we will create one for them and return it.
 *
 * @param options
 */
export const initBC = async (options: BCInitOptions): Promise<BCInitResult> => {
  const error = hasMissingOptions(options);
  if (error) {
    throw error;
  }

  const customerSessionId =
    options.customerSessionId || createUniqueBCSessionId();

  const embedBCOptions: BCEmbedOptions = {
    ...options,
    customerSessionId,
  };

  const { cdApi } = await embedBC(embedBCOptions).catch(e => {
    throw e;
  });

  return {
    cdApi,
    customerSessionId,
  };
};
